import importlib.util, json, subprocess, re, sys
sys.path.insert(0,'output'); sys.path.insert(0,'output/annotation')
from dir import dir_syntax_spec
import InputOutputInfoGeneratorDir, ParallelizabilityInfoGeneratorDir
print("imports OK; classes:", InputOutputInfoGeneratorDir.InputOutputInfoGeneratorDir, ParallelizabilityInfoGeneratorDir.ParallelizabilityInfoGeneratorDir)
j=json.load(open('output/annotation/dir.json'))
opts, pos = dir_syntax_spec[0]
# 1. help coverage
help_=subprocess.run(['/usr/bin/dir','--help'],capture_output=True,text=True).stdout
help_opts=set(re.findall(r'(?m)^\s*(-[A-Za-z0-9])?,?\s*(--[a-z-]+)?',help_))
hs=set()
for m in re.finditer(r'(?m)^  (?:(-\w),?\s*)?(--[\w-]+)?',help_):
    for g in m.groups():
        if g: hs.add(g)
spec_spellings=set()
for o in opts:
    spec_spellings.add(o.flag); spec_spellings.update(o.alias)
print("in help but not spec:", hs-spec_spellings)
print("in spec but not help:", spec_spellings-hs)
json_spellings=set()
for e in j['flag']: json_spellings.update(e if isinstance(e,list) else [e])
for e in j['option']: json_spellings.update(s for s in e[:-1])
print("spec vs json mismatch:", spec_spellings ^ json_spellings)
# json flags/options agree with spec kinds
spec_flags={s for o in opts if o.kind=="Flag" for s in [o.flag]+o.alias}
