# 2. run the binary with each spelling
import os, tempfile
cwd='/tmp/dirtest'
bad=[]
def run(args):
    r=subprocess.run(['/usr/bin/dir']+args+['a'],cwd=cwd,capture_output=True,text=True)
    return r
for o in opts:
    for s in [o.flag]+o.alias:
        if s in ('--help','--version'): continue
        if o.kind=="Flag":
            r=run([s]); 
            if r.returncode!=0: bad.append((s,r.stderr.strip()))
        elif o.choices is not None:
            for c in o.choices:
                arg = s if c=="" else (f"{s}={c}")
                r=run([arg]+(['-l'] if s=='--time-style' else []))
                if r.returncode!=0: bad.append((arg,r.stderr.strip()))
            r=run([f"{s}=bogus"])
            if r.returncode==0 and s!='--time-style': bad.append((f"{s}=bogus","ACCEPTED"))
        else:
            sample={'Size':'K','Glob':'*.o','Integer':'8','TimeStyle':'long-iso'}[o.kind]
            forms=[f"{s}={sample}"] if s.startswith('--') else [f"{s}{sample}", s, sample]
            if s.startswith('--'): forms=[[f"{s}={sample}"],[s,sample]]
            else: forms=[[f"{s}{sample}"],[s,sample]]
            for f in forms:
                r=run(f+(['-l'] if 'time-style' in s else []))
                if r.returncode!=0: bad.append((f,r.stderr.strip()))
print("binary rejections:", bad or "none")
